/**
 * Messages, cut 5: a text as it goes out through Quo (`to-dos/gc-mode/messages/BUILD_PLAN.md` → Cut 5, `quo-send`).
 * Pure: the edge function reads the number, its opt-out, our last text to it and the sender, asks `planSend` what to
 * send, calls Quo's `POST /v1/messages` with the request, and writes the line with the id Quo answers with
 * (`sentQuoId`). The text is `compose.ts`'s `textToSend`: one text, the opt-out line after a blank line when a rule says.
 *
 * Every text goes from its box's number (R6: the company number, or the bids number once it has one), whoever sends it,
 * so a reply lands back in the thread whoever answers. Quo's API sends text only, up to 1,600 characters: a photo goes
 * as a link line, which the caller adds before it asks.
 */
import { numberName, type Mailbox } from '../messages/boxes.ts'
import { type ComposeCompany, type LinkLine, type OptoutRecord, optoutReason, textToSend } from '../messages/textOut.ts'
import type { ThreadMessage } from '../messages/thread.ts'
import { type QuoLine, toE164 } from './events.ts'

/** The most a text sent by Quo's API carries. */
export const QUO_MAX_CHARACTERS = 1600

/**
 * Why a text goes. A person's reply and the app's nudge follow the opt-out line's rules. The app's answer to HELP and
 * its confirmation of a stop carry their own STOP or START words, so they take no line.
 */
export type SendPurpose = 'reply' | 'nudge' | 'answer' | 'confirm'

export interface QuoSendInput {
  purpose: SendPurpose
  contactId: string
  /** The `contact_channels` row of the number. */
  channelId: string | null
  /** Their number, as the record has it. */
  to: string | null
  /** The number sent STOP to the box it goes from (`stoppedOn`). */
  optedOut: boolean
  body: string
  links?: readonly LinkLine[]
  /** Our newest text to this number from this box (ms), or null when we never texted it from there. */
  lastOurTextAt: number | null
  /** The person left the opt-out line off this one text, on the silence reason only. */
  held?: boolean
  now: number
  company: ComposeCompany
  /** The box it goes from (`sendBox`, R6): the line keeps it and names its number. */
  mailbox: Mailbox
  /** That box's number's Quo id (`PN…`): the text's From. */
  fromNumberId: string
  /** Who sends it: one of ours, with their Quo user id when they have a seat, or null for the app. */
  sender: { userId: string; quoUserId: string | null; name: string } | null
  jobId: string | null
}

/** The body of Quo's `POST /v1/messages`. */
export interface QuoSendRequest {
  content: string
  from: string
  to: string[]
  userId?: string
}

/** The line the send writes: the spine's `ThreadMessage` fields for a text out. `quoId` comes from Quo's answer. */
export interface SentLine extends Pick<ThreadMessage, 'contactId' | 'jobId' | 'at' | 'who' | 'body'> {
  channelId: string | null
  channel: 'text'
  direction: 'out'
  whoUserId: string | null
  optoutLine: OptoutRecord | null
  /** `messages.mailbox`: the box it went from. */
  mailbox: Mailbox
}

export type SendRefusal = 'empty' | 'no-number' | 'not-a-number' | 'stopped' | 'too-long'

export type QuoSendPlan =
  | { ok: false; refused: SendRefusal; words: string }
  | { ok: true; request: QuoSendRequest; line: SentLine; segments: number; characters: number }

/** The words on a refusal, each a sentence a person can act on. */
export function refusalWords(refused: SendRefusal, characters = 0): string {
  switch (refused) {
    case 'empty':
      return 'Write the message first.'
    case 'no-number':
      return 'They have no mobile number on file. Add one on the To line and the text can go.'
    case 'not-a-number':
      return 'That number does not read as a mobile number. Fix it on the To line and the text can go.'
    case 'stopped':
      return 'They sent STOP. The app will not send this text.'
    case 'too-long':
      return `${characters} characters is more than a text can carry. Send it as an email, or make it shorter.`
  }
}

/** Who a sent line names: "Robert · from the company number", or the app's own, from `box`'s number. */
export function sentWho(sender: QuoSendInput['sender'], box: Mailbox = 'team'): string {
  return `${sender ? sender.name : 'The app'} · from ${numberName(box)}`
}

/**
 * What to send, or why not. A number that sent STOP gets nothing but the one confirmation of a stop Quo did not catch.
 * The line records the opt-out line's reason, or `held`, so the next text reads the silence from it.
 */
export function planSend(input: QuoSendInput): QuoSendPlan {
  const refuse = (refused: SendRefusal, characters = 0): QuoSendPlan => ({ ok: false, refused, words: refusalWords(refused, characters) })
  if (!input.body.trim()) return refuse('empty')
  if (!input.to?.trim()) return refuse('no-number')
  const to = toE164(input.to)
  if (!to) return refuse('not-a-number')
  if (input.optedOut && input.purpose !== 'confirm') return refuse('stopped')
  const ownWords = input.purpose === 'answer' || input.purpose === 'confirm'
  const sent = textToSend({
    body: input.body,
    links: input.links,
    reason: ownWords ? null : optoutReason(input.lastOurTextAt, input.now),
    held: input.held,
    company: input.company,
  })
  if (sent.characters > QUO_MAX_CHARACTERS) return refuse('too-long', sent.characters)
  const userId = input.sender?.quoUserId ?? undefined
  return {
    ok: true,
    request: { content: sent.text, from: input.fromNumberId, to: [to], ...(userId ? { userId } : {}) },
    line: {
      contactId: input.contactId,
      channelId: input.channelId,
      jobId: input.jobId,
      channel: 'text',
      direction: 'out',
      at: new Date(input.now).toISOString(),
      who: sentWho(input.sender, input.mailbox),
      whoUserId: input.sender?.userId ?? null,
      body: sent.text,
      optoutLine: sent.optout,
      mailbox: input.mailbox,
    },
    segments: sent.segments,
    characters: sent.characters,
  }
}

/** The message id in Quo's answer to a send, for `messages.quo_id`; null when the answer does not carry one. */
export function sentQuoId(answer: unknown): string | null {
  if (!answer || typeof answer !== 'object') return null
  const top = answer as Record<string, unknown>
  const data = top.data && typeof top.data === 'object' && !Array.isArray(top.data) ? (top.data as Record<string, unknown>) : top
  return typeof data.id === 'string' && data.id.trim() ? data.id.trim() : null
}

/**
 * Our send's line, written under the id Quo answered with. When Quo's delivery event wrote a line there first, the
 * send's fields win: who sent it, its words, its time, its job and its opt-out line. The event's ending and media stay.
 * With `mergeSent` in `events.ts`, the two writes end on the same line in either order.
 */
export function sendOver(prev: QuoLine | null, sent: SentLine, quoId: string): QuoLine {
  return {
    quoId,
    contactId: sent.contactId,
    channelId: sent.channelId,
    jobId: sent.jobId,
    channel: 'text',
    direction: 'out',
    at: sent.at,
    who: sent.who,
    whoUserId: sent.whoUserId,
    body: sent.body,
    recordingUrl: null,
    transcript: null,
    summary: null,
    durationSeconds: null,
    media: prev?.media ?? [],
    optoutLine: sent.optoutLine,
    delivery: prev?.delivery ?? null,
    mailbox: sent.mailbox,
  }
}
